// stream.js: show the answer piece by piece as the backend sends it
const out = document.querySelector("#answer");
const askBtn = document.querySelector("#ask");
const stopBtn = document.querySelector("#stop");
let controller = null;

async function askStream(question) {
  controller = new AbortController();              // lets the Stop button cancel
  out.textContent = "";
  askBtn.disabled = true;
  stopBtn.disabled = false;
  try {
    const res = await fetch("/ask/stream", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
      signal: controller.signal,                   // connects fetch to the controller
    });
    if (!res.ok) throw new Error(`Server said ${res.status}`);
    const reader = res.body.getReader();           // read the body as it arrives
    const decoder = new TextDecoder();             // bytes -> text (UTF-8)
    while (true) {
      const { done, value } = await reader.read(); // value is one chunk of bytes
      if (done) break;
      out.textContent += decoder.decode(value, { stream: true });
    }
  } catch (err) {
    if (err.name === "AbortError") out.textContent += " [stopped]";
    else out.textContent = "Sorry, something went wrong: " + err.message;
  } finally {
    askBtn.disabled = false;
    stopBtn.disabled = true;
  }
}

askBtn.addEventListener("click", () => askStream(document.querySelector("#q").value));
stopBtn.addEventListener("click", () => controller?.abort());

