const API = "http://localhost:8000";

async function ask(question) {
  out.textContent = "Thinking...";                     // loading state
  button.disabled = true;
  try {
    const res = await fetch(`${API}/ask`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });
    if (!res.ok) throw new Error(`Server said ${res.status}`);  // 4xx/5xx
    const data = await res.json();
    out.textContent = data.answer + "\n\n" +
      data.sources.map((s) => "- " + s.title).join("\n");
  } catch (err) {
    out.textContent = "Sorry, something went wrong: " + err.message;
  } finally {
    button.disabled = false;
  }
}

