// AskBox.tsx
import { useState } from "react";

type Props = { apiUrl: string };
type AskResponse = { answer: string };

export function AskBox({ apiUrl }: Props) {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function ask() {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`${apiUrl}/ask`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question }),
      });
      if (!res.ok) throw new Error(`Server said ${res.status}`);  // 4xx/5xx
      const data: AskResponse = await res.json();
      setAnswer(data.answer);             // state change -> React re-renders
    } catch (err) {
      setAnswer(null);
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);                  // always runs, so the button never stays stuck
    }
  }

  return (
    <div>
      <label htmlFor="question">Your question</label>
      <input
        id="question"
        value={question}
        onChange={(e) => setQuestion(e.target.value)}
      />
      <button onClick={ask} disabled={loading || !question}>Ask</button>
      {loading && <p>Thinking...</p>}
      {error && <p role="alert">Sorry, something went wrong: {error}</p>}
      {!loading && answer && <p>{answer}</p>}
    </div>
  );
}

class Order:
    VAT_RATE = 0.12                      # class attribute, shared

    def __init__(self, order_id, customer):
        self.order_id = order_id          # instance attributes
        self.customer = customer
        self.lines = []

    def add_line(self, sku, qty, unit_price):
        if qty <= 0:
            raise ValueError(f"qty must be positive, got {qty}")
        self.lines.append((sku, qty, unit_price))

    def total(self):
        net = sum(q * p for _, q, p in self.lines)
        return round(net * (1 + self.VAT_RATE), 2)

    @property                             # read like an attribute: o1.line_count
    def line_count(self):
        return len(self.lines)

    @classmethod                          # another way to build an Order
    def from_row(cls, row):
        return cls(int(row["order_id"]), row["customer"].strip())

    @staticmethod                         # a helper that needs no self or cls
    def parse_price(text):
        return float(text.replace(",", "."))

    def __repr__(self):                   # for developers: REPL, logs, lists
        return f"Order({self.order_id}, {self.customer!r}, {len(self.lines)} lines)"

    def __str__(self):                    # for people: print() and f-strings
        return f"Order {self.order_id} for {self.customer}"

o1 = Order(1001, "Lindqvist Bakery")
o1.add_line("flour-25kg", 2, 18.50)
print(repr(o1), o1.total())   # Order(1001, 'Lindqvist Bakery', 1 lines) 41.44
