from abc import ABC, abstractmethod

class Notifier(ABC):                  # ABC: a base class that cannot be used directly
    @abstractmethod
    def send(self, to, text):         # every child must write its own send()
        ...

class EmailNotifier(Notifier):        # inheritance: is a Notifier
    def send(self, to, text):
        print(f"EMAIL to {to}: {text}")

class SmsNotifier(Notifier):
    def send(self, to, text):
        print(f"SMS to {to}: {text[:160]}")

class WebhookNotifier(Notifier):      # forgot to write send()
    pass

try:
    WebhookNotifier()
except TypeError as err:
    print(err)   # Can't instantiate abstract class WebhookNotifier ... send (wording varies by version)

class OrderService:
    def __init__(self, notifier: Notifier):
        self.notifier = notifier      # composition: has a Notifier

    def confirm(self, order, contact):
        self.notifier.send(contact, f"Order {order.order_id} confirmed")

