# Your own exception classes: a small family, so callers can catch at the right level
class IntegrationError(Exception):
    """Anything that went wrong talking to a customer system."""

class RetryableError(IntegrationError):
    """Temporary: try again later (timeouts, 429, 503)."""

class BadRecordError(IntegrationError):
    def __init__(self, record_id, reason):
        super().__init__(f"record {record_id}: {reason}")
        self.record_id = record_id    # extra data the caller can use

for exc in [RetryableError("supplier API returned 503"), BadRecordError(77, "missing sku")]:
    try:
        raise exc
    except RetryableError as err:
        print("retry later:", err)    # retry later: supplier API returned 503
    except IntegrationError as err:
        print("skip and report:", err)  # skip and report: record 77: missing sku

import asyncio, random
from email.utils import parsedate_to_datetime
from datetime import datetime, timezone
import httpx

class RateLimiter:
    """Allow at most `per_second` request starts per second."""
    def __init__(self, per_second: float):
        self.interval, self.next_at = 1 / per_second, 0.0
        self.lock = asyncio.Lock()
    async def wait(self):
        async with self.lock:
            now = asyncio.get_running_loop().time()
            delay = max(0.0, self.next_at - now)
            self.next_at = max(now, self.next_at) + self.interval
        await asyncio.sleep(delay)

RETRY_STATUS = {429, 500, 502, 503, 504}

def retry_after_seconds(value: str | None, default: float) -> float:
    """Retry-After is either a number of seconds or an HTTP date."""
    if not value:
        return default
    try:
        return float(value)                       # "5"
    except ValueError:
        when = parsedate_to_datetime(value)       # "Wed, 01 Apr 2026 10:00:05 GMT"
        return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())

async def get_with_retry(client, sem, limiter, url, tries=4):
    for attempt in range(tries):
        last_try = attempt == tries - 1
        try:
            async with sem:                      # cap in-flight requests
                await limiter.wait()             # cap requests per second
                r = await client.get(url)
        except (httpx.TimeoutException, httpx.ConnectError):
            if last_try:
                raise                            # out of attempts: let the caller log it
            wait = 2 ** attempt                  # network trouble: plain backoff
        else:
            if r.status_code not in RETRY_STATUS:
                r.raise_for_status()             # other 4xx: retrying will not help
                return r.json()
            if last_try:
                r.raise_for_status()             # give up with the real HTTP error
            wait = retry_after_seconds(r.headers.get("Retry-After"), 2 ** attempt)
        await asyncio.sleep(wait + random.random())   # backoff with jitter, never after the last try
